{"sql": "-- Create helper functions in the public schema

-- Function to check if a user is a channel owner
CREATE OR REPLACE FUNCTION public.is_channel_owner(channel_id uuid, user_id uuid)
RETURNS boolean AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.channels 
        WHERE id = channel_id AND owner_id = user_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to check if a user is a channel moderator
CREATE OR REPLACE FUNCTION public.is_channel_moderator(channel_id uuid, user_id uuid)
RETURNS boolean AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.channel_moderators 
        WHERE channel_id = channel_id AND user_id = user_id
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to check if a user can moderate a channel (is owner or moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(channel_id uuid, user_id uuid)
RETURNS boolean AS $$
BEGIN
    RETURN public.is_channel_owner(channel_id, user_id) OR public.is_channel_moderator(channel_id, user_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;"}

