{"sql": "-- Users Table Access Rules

-- SELECT: Users can read all public user profiles (username, created_at)
CREATE POLICY users_select_policy ON public.users
FOR SELECT USING (is_public = true);

-- UPDATE: Users can only modify their own profile
CREATE POLICY users_update_policy ON public.users
FOR UPDATE USING (id = current_setting('app.current_user_id')::uuid);

-- DELETE: Users can only delete their own account
CREATE POLICY users_delete_policy ON public.users
FOR DELETE USING (id = current_setting('app.current_user_id')::uuid);

-- Users can always view their own profile
CREATE POLICY users_own_profile_policy ON public.users
FOR SELECT USING (id = current_setting('app.current_user_id')::uuid);"}

{"sql": "-- Channels Table Access Rules

-- SELECT: Everyone can read public channel information
CREATE POLICY channels_select_policy ON public.channels
FOR SELECT USING (is_public = true);

-- INSERT: Any authenticated user can create a channel (becomes owner)
CREATE POLICY channels_insert_policy ON public.channels
FOR INSERT WITH CHECK (true);

-- UPDATE: Only channel owners can modify channel details
CREATE POLICY channels_update_policy ON public.channels
FOR UPDATE USING (owner_id = current_setting('app.current_user_id')::uuid);

-- DELETE: Only channel owners can delete channels
CREATE POLICY channels_delete_policy ON public.channels
FOR DELETE USING (owner_id = current_setting('app.current_user_id')::uuid);

-- Channel owners can always see their own channels
CREATE POLICY channels_owner_view_policy ON public.channels
FOR SELECT USING (owner_id = current_setting('app.current_user_id')::uuid);"}

{"sql": "-- Posts Table Access Rules

-- SELECT: Users can read all posts in channels they have access to
CREATE POLICY posts_select_policy ON public.posts
FOR SELECT USING (
    EXISTS (
        SELECT 1 FROM public.channels 
        WHERE channels.id = posts.channel_id 
        AND (channels.is_public = true OR channels.owner_id = current_setting('app.current_user_id')::uuid)
    )
);

-- INSERT: Authenticated users can create posts in any channel
CREATE POLICY posts_insert_policy ON public.posts
FOR INSERT WITH CHECK (author_id = current_setting('app.current_user_id')::uuid);

-- UPDATE: Post authors OR channel moderators OR channel owners can edit posts
CREATE POLICY posts_update_policy ON public.posts
FOR UPDATE USING (
    author_id = current_setting('app.current_user_id')::uuid
    OR EXISTS (
        SELECT 1 FROM public.channels 
        WHERE channels.id = posts.channel_id 
        AND (public.can_moderate_channel(channels.id, current_setting('app.current_user_id')::uuid))
    )
);

-- DELETE: Post authors OR channel moderators OR channel owners can delete posts
CREATE POLICY posts_delete_policy ON public.posts
FOR DELETE USING (
    author_id = current_setting('app.current_user_id')::uuid
    OR EXISTS (
        SELECT 1 FROM public.channels 
        WHERE channels.id = posts.channel_id 
        AND (public.can_moderate_channel(channels.id, current_setting('app.current_user_id')::uuid))
    )
);"}

{"sql": "-- Channel Moderators Table Access Rules

-- SELECT: Users can see moderator lists for channels
CREATE POLICY channel_moderators_select_policy ON public.channel_moderators
FOR SELECT USING (true);

-- INSERT: Only channel owners can add moderators
CREATE POLICY channel_moderators_insert_policy ON public.channel_moderators
FOR INSERT WITH CHECK (
    EXISTS (
        SELECT 1 FROM public.channels 
        WHERE channels.id = channel_moderators.channel_id 
        AND channels.owner_id = current_setting('app.current_user_id')::uuid
    )
);

-- DELETE: Channel owners can remove moderators; moderators can remove themselves
CREATE POLICY channel_moderators_delete_policy ON public.channel_moderators
FOR DELETE USING (
    EXISTS (
        SELECT 1 FROM public.channels 
        WHERE channels.id = channel_moderators.channel_id 
        AND channels.owner_id = current_setting('app.current_user_id')::uuid
    )
    OR user_id = current_setting('app.current_user_id')::uuid
);"}

{"sql": "-- Create additional indexes for better RLS performance

-- Index on channels for owner lookups
CREATE INDEX IF NOT EXISTS idx_channels_owner ON public.channels (owner_id);

-- Index on posts for author lookups
CREATE INDEX IF NOT EXISTS idx_posts_author ON public.posts (author_id);

-- Index on comments for author lookups
CREATE INDEX IF NOT EXISTS idx_comments_author ON public.comments (author_id);

-- Index on channel_moderators for user lookups
CREATE INDEX IF NOT EXISTS idx_channel_moderators_user_id ON public.channel_moderators (user_id);"}

